import React from 'react';

interface CodeEditorProps {
  code: string;
  onChange: (val: string) => void;
  readOnly?: boolean;
}

export const CodeEditor: React.FC<CodeEditorProps> = ({ code, onChange, readOnly = false }) => {

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Tab') {
      e.preventDefault();
      const start = e.currentTarget.selectionStart;
      const end = e.currentTarget.selectionEnd;
      // Insert 4 spaces for tab
      const newValue = code.substring(0, start) + "    " + code.substring(end);
      onChange(newValue);

      // Need to defer cursor move to next tick
      setTimeout(() => {
        if(e.target instanceof HTMLTextAreaElement) {
           e.target.selectionStart = e.target.selectionEnd = start + 4;
        }
      }, 0);
    }
  };

  return (
    <div className="relative w-full h-full bg-cyber-dark font-mono text-sm border-r border-cyber-slate flex flex-col">
      <div className="flex items-center justify-between px-4 py-2 bg-cyber-black border-b border-cyber-slate text-gray-400 text-xs select-none">
        <span>main.py</span>
        <span>Python 3.12</span>
      </div>
      <div className="relative flex-1 flex">
        {/* Line Numbers */}
        <div className="w-10 bg-cyber-black text-gray-600 text-right pr-2 pt-4 select-none leading-6 font-mono">
            {code.split('\n').map((_, i) => <div key={i}>{i + 1}</div>)}
        </div>

        {/* Editor Area */}
        <textarea
          value={code}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={handleKeyDown}
          spellCheck={false}
          readOnly={readOnly}
          className="flex-1 bg-transparent text-gray-300 resize-none outline-none p-4 leading-6 selection:bg-cyber-neon selection:text-black"
          placeholder="# Write your code here..."
        />
      </div>
    </div>
  );
};

import React, { useEffect, useRef } from 'react';
import { LogEntry, MessageType } from '../types';

interface ConsoleProps {
  logs: LogEntry[];
}

export const Console: React.FC<ConsoleProps> = ({ logs }) => {
  const endRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  const getColor = (type: MessageType) => {
    switch (type) {
      case MessageType.ERROR: return 'text-cyber-red';
      case MessageType.SUCCESS: return 'text-cyber-green';
      case MessageType.SYSTEM: return 'text-blue-400';
      case MessageType.STORY: return 'text-yellow-400 italic';
      default: return 'text-gray-300';
    }
  };

  return (
    <div className="w-full h-full bg-black font-mono text-xs p-4 overflow-y-auto border-t border-cyber-slate">
      <div className="text-gray-500 mb-2 select-none">root@cipher-terminal:~/protocol$</div>
      {logs.map((log) => (
        <div key={log.id} className={`mb-1 ${getColor(log.type)}`}>
          <span className="opacity-50 mr-2">[{log.timestamp}]</span>
          <span>{log.type === MessageType.ERROR ? 'ERROR: ' : ''}{log.content}</span>
        </div>
      ))}
      <div ref={endRef} />
    </div>
  );
};

