import React, { useState, useEffect, useCallback } from 'react';
import { GameState, LogEntry, MessageType, StorySegment } from './types';
import { LEVELS } from './data/levels';
import { executeCode } from './services/mockPython';
import { CodeEditor } from './components/CodeEditor';
import { Console } from './components/Console';
import { Visualizer } from './components/Visualizer';
import { StoryOverlay } from './components/StoryOverlay';

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState>({
    currentLevelId: 1,
    xp: 0,
    isStoryOpen: true,
    currentStorySegment: 0,
    storyQueue: LEVELS[0].storyStart,
    isLevelComplete: false,
    code: LEVELS[0].initialCode,
    logs: [{
      id: 'init',
      type: MessageType.SYSTEM,
      content: 'Connecting to Global Defense Grid...',
      timestamp: new Date().toLocaleTimeString()
    }],
    status: 'idle'
  });

  const [examModalOpen, setExamModalOpen] = useState(false);

  const currentLevel = LEVELS.find(l => l.id === gameState.currentLevelId) || LEVELS[0];

  const addLog = (type: MessageType, content: string) => {
    setGameState(prev => ({
      ...prev,
      logs: [...prev.logs, {
        id: Math.random().toString(36).substr(2, 9),
        type,
        content,
        timestamp: new Date().toLocaleTimeString()
      }]
    }));
  };

  // Story Navigation
  const handleStoryNext = () => {
    if (gameState.currentStorySegment < gameState.storyQueue.length - 1) {
      setGameState(prev => ({ ...prev, currentStorySegment: prev.currentStorySegment + 1 }));
    } else {
      // Story sequence finished
      setGameState(prev => ({ ...prev, isStoryOpen: false, currentStorySegment: 0 }));

      // If the level was already complete, move to next level
      if (gameState.isLevelComplete) {
         if (gameState.currentLevelId < LEVELS.length) {
            const nextLevelId = gameState.currentLevelId + 1;
            const nextLevel = LEVELS.find(l => l.id === nextLevelId);
            if (nextLevel) {
                setGameState(prev => ({
                    ...prev,
                    currentLevelId: nextLevelId,
                    isLevelComplete: false,
                    storyQueue: nextLevel.storyStart,
                    isStoryOpen: true,
                    code: nextLevel.initialCode,
                    status: 'idle',
                    logs: [] // Clear logs for new level
                }));
            }
         } else {
             // End of Demo
             alert("End of Demo! Thanks for playing Project Singularity.");
         }
      }
    }
  };

  const handleRunCode = () => {
    setGameState(prev => ({ ...prev, status: 'running' }));
    addLog(MessageType.USER, 'Executing script...');

    setTimeout(() => {
      const result = executeCode(gameState.code, currentLevel);

      if (result.success) {
        setGameState(prev => ({ ...prev, status: 'success', isLevelComplete: true }));
        addLog(MessageType.SUCCESS, result.message);
        if (result.output) addLog(MessageType.SYSTEM, `OUTPUT: ${result.output}`);

        // Trigger end story after a delay
        setTimeout(() => {
           setGameState(prev => ({
               ...prev,
               isStoryOpen: true,
               storyQueue: currentLevel.storyEnd,
               currentStorySegment: 0,
               xp: prev.xp + 100
           }));
        }, 1500);

      } else {
        setGameState(prev => ({ ...prev, status: 'failed' }));
        addLog(MessageType.ERROR, result.message);
        if (result.output) addLog(MessageType.SYSTEM, `OUTPUT: ${result.output}`);
      }
    }, 800); // Fake latency
  };

  const handleReset = () => {
      setGameState(prev => ({...prev, code: currentLevel.initialCode, status: 'idle'}));
      addLog(MessageType.SYSTEM, "Code reset to default.");
  };

  // Keyboard shortcut for Story
  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
        if (gameState.isStoryOpen) {
            if (e.key === 'Enter' || e.key === ' ') {
                handleStoryNext();
            }
        }
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [gameState.isStoryOpen, gameState.currentStorySegment, gameState.storyQueue]);

  return (
    <div className="flex h-screen w-screen bg-cyber-black text-gray-200 font-sans selection:bg-cyber-neon selection:text-black overflow-hidden relative">

      {/* Scanline CRT Overlay */}
      <div className="absolute inset-0 z-50 pointer-events-none crt-overlay opacity-30"></div>

      {/* Story Overlay */}
      {gameState.isStoryOpen && (
        <StoryOverlay 
          segment={gameState.storyQueue[gameState.currentStorySegment]} 
          onNext={handleStoryNext} 
          isLast={gameState.currentStorySegment === gameState.storyQueue.length - 1}
        />
      )}

      {/* Exam Modal */}
      {examModalOpen && (
        <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/80 backdrop-blur-sm" onClick={() => setExamModalOpen(false)}>
            <div className="bg-white text-black p-8 max-w-lg rounded shadow-2xl border-l-8 border-yellow-500" onClick={e => e.stopPropagation()}>
                <h2 className="text-2xl font-bold mb-4 flex items-center gap-2">
                    <span className="text-yellow-600">⚠</span> ICSE EXAM ALERT
                </h2>
                <div className="mb-4">
                    <h3 className="font-bold text-gray-700 uppercase text-sm mb-1">Topic</h3>
                    <p className="text-gray-900">{currentLevel.icseTopic}</p>
                </div>
                <div className="bg-yellow-50 p-4 rounded border border-yellow-200">
                    <p className="font-serif italic text-lg mb-2">"{currentLevel.icseQuestion.question}"</p>
                    <div className="flex justify-between items-center mt-4">
                        <span className="text-xs font-bold bg-yellow-200 px-2 py-1 rounded text-yellow-800">
                            {currentLevel.icseQuestion.marks} Marks
                        </span>
                        <button 
                            className="text-sm underline text-blue-600 hover:text-blue-800"
                            onClick={() => alert(`Answer: ${currentLevel.icseQuestion.answer}`)}
                        >
                            Reveal Answer
                        </button>
                    </div>
                </div>
                <button 
                    className="mt-6 w-full bg-gray-900 text-white py-2 font-bold hover:bg-gray-800 transition"
                    onClick={() => setExamModalOpen(false)}
                >
                    Dismiss
                </button>
            </div>
        </div>
      )}

      {/* Sidebar */}
      <div className="w-64 bg-cyber-dark border-r border-cyber-slate flex flex-col justify-between hidden md:flex">
        <div>
          <div className="p-6 border-b border-cyber-slate">
            <h1 className="text-xl font-bold text-white tracking-tighter italic">PROJECT <span className="text-cyber-neon">SINGULARITY</span></h1>
            <div className="text-xs text-gray-500 mt-1">v0.9.1 // IRON REBELLION</div>
          </div>

          <div className="p-6">
            <div className="text-xs uppercase tracking-widest text-gray-500 mb-2">Pilot Stats</div>
            <div className="flex items-center gap-3 mb-4">
                <div className="w-10 h-10 rounded-full bg-cyber-slate border border-gray-600 flex items-center justify-center font-mono font-bold text-cyber-neon">C</div>
                <div>
                    <div className="font-bold">Cipher</div>
                    <div className="text-xs text-cyber-gold">{gameState.xp} XP</div>
                </div>
            </div>

            <div className="space-y-2">
                <div className="text-xs uppercase tracking-widest text-gray-500 mt-6 mb-2">Modules</div>
                {LEVELS.map(l => (
                    <div key={l.id} className={`p-2 text-sm border-l-2 pl-3 ${l.id === gameState.currentLevelId ? 'border-cyber-neon bg-white/5 text-white' : 'border-gray-700 text-gray-500'}`}>
                        {l.id}. {l.title}
                    </div>
                ))}
            </div>
          </div>
        </div>

        <div className="p-4 border-t border-cyber-slate">
           <button 
             onClick={() => setExamModalOpen(true)}
             className="w-full py-3 bg-yellow-600/20 border border-yellow-600 text-yellow-500 hover:bg-yellow-600 hover:text-black transition-all text-xs font-bold uppercase tracking-wider flex items-center justify-center gap-2"
           >
             <span>⚠</span> Exam Prep Mode
           </button>
        </div>
      </div>

      {/* Main Area */}
      <div className="flex-1 flex flex-col min-w-0">

        {/* Header */}
        <header className="h-16 bg-cyber-black border-b border-cyber-slate flex items-center justify-between px-6">
          <div>
            <h2 className="text-lg font-bold text-cyber-neon flex items-center gap-2">
                <span className="w-2 h-2 bg-cyber-neon rounded-full animate-pulse"></span>
                {currentLevel.title}
            </h2>
            <p className="text-xs text-gray-400">{currentLevel.subTitle}</p>
          </div>
          <div className="flex items-center gap-4">
              <button onClick={() => setGameState(prev => ({...prev, isStoryOpen: true, currentStorySegment: 0, storyQueue: currentLevel.storyStart}))} className="text-xs text-gray-400 hover:text-white underline">Replay Briefing</button>
              <div className="px-3 py-1 border border-gray-700 rounded text-xs text-gray-400 bg-gray-900">
                  Target: <span className="text-white">Mainframe</span>
              </div>
          </div>
        </header>

        {/* Workspace */}
        <div className="flex-1 flex flex-col md:flex-row min-h-0">

          {/* Left: Code & Console */}
          <div className="flex-1 flex flex-col min-w-0 border-r border-cyber-slate">
            {/* Description Box */}
            <div className="p-4 bg-cyber-dark border-b border-cyber-slate">
                <p className="text-sm text-gray-300 leading-relaxed">{currentLevel.description}</p>
                <div className="mt-2 text-xs text-cyber-neon bg-cyber-neon/10 p-2 rounded inline-block border border-cyber-neon/30">
                    <span className="font-bold">OBJECTIVE:</span> {currentLevel.objective}
                </div>
            </div>

            {/* Code Editor */}
            <div className="flex-1 min-h-[300px]">
                <CodeEditor 
                    code={gameState.code} 
                    onChange={(val) => setGameState(prev => ({ ...prev, code: val }))} 
                />
            </div>

            {/* Actions Bar */}
            <div className="h-14 bg-cyber-black border-y border-cyber-slate flex items-center justify-end px-4 gap-3">
                <button 
                    onClick={handleReset}
                    className="px-4 py-1 text-xs text-gray-500 hover:text-white transition-colors"
                >
                    RESET CODE
                </button>
                <button 
                    onClick={handleRunCode}
                    disabled={gameState.status === 'running'}
                    className={`px-6 py-2 bg-cyber-neon text-black font-bold font-mono text-sm uppercase tracking-wider hover:bg-white hover:shadow-[0_0_15px_#fff] transition-all disabled:opacity-50 disabled:cursor-not-allowed`}
                >
                    {gameState.status === 'running' ? 'EXECUTING...' : 'RUN SCRIPT_'}
                </button>
            </div>

            {/* Console */}
            <div className="h-48">
                <Console logs={gameState.logs} />
            </div>
          </div>

          {/* Right: Visualization */}
          <div className="w-full md:w-[400px] bg-black flex flex-col">
              <div className="flex-1 relative">
                  <Visualizer level={currentLevel} status={gameState.status} />
              </div>

              {/* Hints Panel */}
              <div className="h-48 bg-cyber-dark border-t border-cyber-slate p-4 overflow-y-auto">
                  <h3 className="text-xs font-bold text-gray-500 uppercase mb-2">A.D.A.M. Assistant</h3>
                  <div className="flex gap-3">
                      <div className="w-8 h-8 rounded bg-cyan-900/50 flex-shrink-0 flex items-center justify-center border border-cyan-800">
                          <span className="text-cyan-400 font-bold text-xs">AI</span>
                      </div>
                      <div className="text-sm text-gray-400">
                          <p className="mb-2">{currentLevel.hint}</p>
                          <p className="text-xs italic text-gray-600">"Remember, indentation matters in Python."</p>
                      </div>
                  </div>
              </div>
          </div>

        </div>
      </div>
    </div>
  );
};

export default App;
